mod solution;

fn main() {
    let cases = [
    (r#"[100, -5, 100, 20]"#, r#"2,0,2,1"#),
    (r#"[5, 5, -1]"#, r#"1,1,0"#),
    (r#"
[5, 5, -1]
"#, r#"1,1,0"#),
    (r#"  
[100, -5, 100, 20]
  "#, r#"2,0,2,1"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS coordinate-compression");
}
